package foodchain

import "strings"

// animals is indexed by verse number (1 = fly ... 8 = horse).
var animals = []string{"", "fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

// comments holds the second line of each verse.
var comments = []string{
	"",
	"I don't know why she swallowed the fly. Perhaps she'll die.",
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

// catchSuffixes holds the extra wording appended to an animal's name
// when it is the target of a "she swallowed X to catch the Y" line.
var catchSuffixes = []string{
	"",
	"",
	" that wriggled and jiggled and tickled inside her",
	"",
	"",
	"",
	"",
	"",
	"",
}

const dieLine = "I don't know why she swallowed the fly. Perhaps she'll die."

// Verse returns the lyrics for the given verse number (1-8).
func Verse(v int) string {
	name := animals[v]
	lines := []string{
		"I know an old lady who swallowed a " + name + ".",
		comments[v],
	}
	for i := v; i > 1; i-- {
		lines = append(lines, "She swallowed the "+name+" to catch the "+
			animals[i-1]+catchSuffixes[i-1]+".")
	}
	if v < 8 {
		lines = append(lines, dieLine)
	}
	return strings.Join(lines, "\n")
}

// Verses returns the lyrics for verses start through end, inclusive.
func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

// Song returns the complete song (verses 1-8).
func Song() string {
	return Verses(1, 8)
}

